        ["Corrigido: o histórico de atividade mostrava linhas internas do script e textos sem tradução para inglês."] = "Fixed: the activity history showed internal script lines and texts without English translation.",

        // ---------- Avisos da Visão geral ----------
        ["O Windows desfez 1 ajuste do app"] = "Windows undid 1 of the app's settings",
        ["Ajustes reaplicados"] = "Settings reapplied",
        ["Os valores do app voltaram ao registro."] = "The app's values are back in the registry.",
        ["Alguns ajustes não voltaram"] = "Some settings didn't come back",
        ["Taxa de atualização ajustada"] = "Refresh rate adjusted",
        ["Este ajuste não tem mais backup."] = "This setting no longer has a backup.",
        ["O backup deste ajuste não foi criado pelo app; reaplique pelo próprio ajuste."] = "This setting's backup wasn't created by the app; reapply it from the setting itself.",
        ["O ajuste não estava aplicado por completo."] = "The setting wasn't fully applied.",
        ["O Windows bloqueou parte dos valores; tente de novo depois de reiniciar."] = "Windows blocked some of the values; try again after restarting.",
        ["O Windows não informou o modo atual do monitor."] = "Windows didn't report the monitor's current mode.",

        // ---------- Textos que ficaram sem inglês em versões anteriores ----------
        ["Acesso rápido"] = "Quick access",
        ["DOWNLOAD SEGURO"] = "SECURE DOWNLOAD",
        ["DOWNLOAD MANUAL"] = "MANUAL DOWNLOAD",
        ["Economia de energia"] = "Power saver",
        ["Uma atualização está pronta"] = "An update is ready",
        ["Aplicando politicas do Editor de Politica de Grupo (diagnostico, nuvem, IA e Push)"] = "Applying Group Policy Editor policies (diagnostics, cloud, AI and Push)",
        ["Assistente de BIOS iniciado"] = "BIOS Assistant started",
        ["Limpeza de arquivos: use a analise e selecao na Limpeza Rapida."] = "File cleanup: use the analysis and selection in Quick Clean.",
        ["Instalador seguro, verificado por SHA256 e pronto para atualizar."] = "Secure installer, verified by SHA256 and ready to update.",
        ["Instalador verificado por SHA256 e configurações preservadas."] = "Installer verified by SHA256 and settings preserved.",
        ["Ligada. A Proteção contra Adulteração está ativa; o Windows gerencia esta configuração. Use a Segurança do Windows para revisar a proteção."] = "On. Tamper Protection is active; Windows manages this setting. Use Windows Security to review the protection.",
        ["Pode mudar algum comportamento do Windows; revise antes. Remove arquivos ou apps: não é desfeito pela reversão."] = "May change some Windows behavior; review first. Removes files or apps: not undone by the revert.",
        ["Restaura o rádio Bluetooth do Windows, corrige os serviços de descoberta, instala o driver oficial do TP-Link UB500 quando detectado e recarrega o adaptador."] = "Restores the Windows Bluetooth radio, fixes the discovery services, installs the official TP-Link UB500 driver when detected and reloads the adapter.",
        ["Seu tema atual continua valendo; o Início oferece uma vez o novo tema Azul meia-noite."] = "Your current theme stays; Home offers the new Midnight Blue theme once.",

        // Notas de versão (página Novidades)
        ["A Central de diagnóstico agora é o único acesso principal aos diagnósticos, evitando duas funções com o mesmo nome e mantendo todas as verificações em um só lugar."] = "The Diagnostics Center is now the single main entry to diagnostics, avoiding two features with the same name and keeping every check in one place.",
        ["Aviso de atualização redesenhado: versão atual e nova, novidades em cartões, selo de download seguro e ações mais claras para atualizar ou continuar depois."] = "Redesigned update notice: current and new version, what's new in cards, a secure download badge and clearer actions to update or continue later.",
        ["Banco de perfis e caminhos da BIOS com atualizações assinadas, sem precisar atualizar o aplicativo para receber novos perfis."] = "BIOS profile and path database with signed updates, with no need to update the app to get new profiles.",
        ["BIOS Advisor agora lê os valores atuais pelo SCEWIN escolhido pelo usuário, sem gravar alterações na BIOS, e mostra o nome exato da opção, o valor e as opções disponíveis."] = "BIOS Advisor now reads the current values through the SCEWIN chosen by the user, without writing changes to the BIOS, and shows the exact option name, value and available choices.",
        ["Com o app em português, páginas e recursos têm nomes em português: Otimização inteligente, Laboratório de desempenho, Assistente de BIOS e Novidades."] = "With the app in Portuguese, pages and features have Portuguese names: Smart optimization, Performance lab, BIOS Assistant and What's new.",
        ["Correções com categorias fixas, ordenação por uso ou segurança, descrições recolhíveis e cartões mais compactos."] = "Fixes with fixed categories, sorting by usage or safety, collapsible descriptions and more compact cards.",
        ["Corrigida a verificação de assinaturas do Windows quando o aplicativo é iniciado pelo PowerShell 7."] = "Fixed the Windows signature check when the app is started from PowerShell 7.",
        ["Fixes: o modo demonstração abre o Início, o Meu PC e as Configurações, e o texto dos botões fica legível nos temas claros."] = "Fixes: demo mode opens Home, My PC and Settings, and button text stays readable in light themes.",
        ["Correções: o modo demonstração abre o Início, o Meu PC e as Configurações, e o texto dos botões fica legível nos temas claros."] = "Fixes: demo mode opens Home, My PC and Settings, and button text stays readable in light themes.",
        ["o modo demonstração abre o Início, o Meu PC e as Configurações, e o texto dos botões fica legível nos temas claros."] = "demo mode opens Home, My PC and Settings, and button text stays readable in light themes.",
        ["Gráficos com curva suave e valor ao passar o mouse, histórico em linha do tempo, abas segmentadas e animações mais curtas."] = "Charts with smooth curves and values on hover, timeline history, segmented tabs and shorter animations.",
        ["Histórico de atividade com busca, filtros por resultado, cores e mensagens técnicas disponíveis ao passar o mouse."] = "Activity history with search, result filters, colors and technical messages on hover.",
        ["Início mais limpo: estado do PC com nota de saúde e indicadores reais (temperaturas, saúde, estabilidade e drivers), números ao vivo de processador, memória, placa de vídeo e rede e atalhos."] = "Cleaner Home: PC status with a health score and real indicators (temperatures, health, stability and drivers), live processor, memory, graphics card and network numbers, and shortcuts.",
        ["Leituras da BIOS salvas entre aberturas e invalidadas quando a placa ou a versão da BIOS muda; a nota de otimização passa a considerar os valores lidos."] = "BIOS readings saved between launches and invalidated when the board or BIOS version changes; the optimization score now takes the read values into account.",
        ["Nova Central de diagnóstico com verificações de sistema, drivers, serviços, rede, Bluetooth e integridade do Windows."] = "New Diagnostics Center with system, driver, service, network, Bluetooth and Windows integrity checks.",
        ["Nova correção de Bluetooth em Correções: identifica o adaptador físico, restaura o rádio e os serviços de descoberta, recarrega o dispositivo e instala o driver oficial do TP-Link UB500 somente quando esse modelo é detectado."] = "New Bluetooth fix in Fixes: identifies the physical adapter, restores the radio and discovery services, reloads the device and installs the official TP-Link UB500 driver only when that model is detected.",
        ["Nova página Meu PC: especificações lidas na hora (processador, placa de vídeo e driver, memória, placa-mãe e BIOS, sistema, rede e armazenamento) e Copiar resumo para o suporte."] = "New My PC page: specs read on the spot (processor, graphics card and driver, memory, motherboard and BIOS, system, network and storage) and Copy summary for support.",
        ["Novo visual: tema Azul meia-noite (preto, branco e azul) como padrão, ícone azul e barra lateral em categorias recolhíveis, com o monitor ao vivo e a licença no rodapé."] = "New look: Midnight Blue theme (black, white and blue) by default, blue icon and a sidebar with collapsible categories, with the live monitor and license at the bottom.",
        ["O atualizador agora usa um feed público de releases como fallback quando a API do GitHub atinge o limite de requisições, evitando que novas versões deixem de aparecer."] = "The updater now falls back to a public releases feed when the GitHub API hits its rate limit, so new versions don't go missing.",
        ["Página Correções com busca rápida, filtro por categoria e cartões mais destacados para encontrar e executar reparos com menos cliques."] = "Fixes page with quick search, category filter and more prominent cards to find and run repairs in fewer clicks.",
        ["Saúde do PC com atalhos clicáveis para abrir diretamente os componentes e reparos relacionados."] = "PC health with clickable shortcuts that open the related components and repairs directly.",
        ["Versão do aplicativo sincronizada com o instalador e com o mecanismo de atualizações para garantir que a nova build seja reconhecida corretamente."] = "App version synced with the installer and the update engine so the new build is recognized correctly.",
    };

    private static readonly (Regex Regex, Func<Match, string> Build)[] ReferencesPatterns =
    {
        P(@"^O Windows desfez (\d+) ajustes do app$", m => $"Windows undid {m.Groups[1].Value} of the app's settings"),
        P(@"^Uma atualização ou outro programa trocou os valores de: (.+?)( e mais (\d+))?\. Reaplique para voltar ao que você tinha escolhido\.$",
            m => $"An update or another program changed the values of: {m.Groups[1].Value}{(m.Groups[2].Success ? $" and {m.Groups[3].Value} more" : "")}. Reapply to go back to what you had chosen."),
        P(@"^Usar (\d+) Hz$", m => $"Use {m.Groups[1].Value} Hz"),
        P(@"^Seu monitor está em (\d+) Hz, mas aceita (\d+) Hz$", m => $"Your monitor is at {m.Groups[1].Value} Hz, but supports {m.Groups[2].Value} Hz"),
        P(@"^Em (\d+x\d+), a taxa maior deixa o movimento mais fluido e reduz o atraso nos jogos\. Para voltar: Configurações → Sistema → Tela → Tela avançada\.$",
            m => $"At {m.Groups[1].Value}, the higher rate makes motion smoother and lowers input lag in games. To go back: Settings → System → Display → Advanced display."),
        P(@"^O monitor agora roda a (\d+) Hz\.$", m => $"The monitor now runs at {m.Groups[1].Value} Hz."),
        P(@"^O Windows recusou a troca para (\d+) Hz \(código (-?\d+)\)\.$", m => $"Windows refused the switch to {m.Groups[1].Value} Hz (code {m.Groups[2].Value})."),
        P(@"^(?:\[ETAPA\] |Etapa: )(.+)$", m => $"Step: {T(m, 1)}"),
        P(@"^O relógio do Windows está (\d+) (minutos|horas) (atrasado|adiantado)$", m => $"The Windows clock is {m.Groups[1].Value} {(m.Groups[2].Value == "horas" ? "hours" : "minutes")} {(m.Groups[3].Value == "atrasado" ? "behind" : "ahead")}"),
        P(@"^Configurações do (.+): arquivo (travado \(somente leitura\)|destravado)$", m => $"{m.Groups[1].Value} settings: file {(m.Groups[2].Value == "destravado" ? "unlocked" : "locked (read-only)")}"),
        P(@"^Feche o (.+) antes: ele regrava as configurações ao fechar\.$", m => $"Close {m.Groups[1].Value} first: it rewrites its settings when it closes."),
        P(@"^Aplicando perfil NVIDIA no (.+)$", m => $"Applying NVIDIA profile to {m.Groups[1].Value}"),
        P(@"^Restaurando o perfil NVIDIA do (.+)$", m => $"Restoring {m.Groups[1].Value}'s NVIDIA profile"),
        P(@"^Perfil NVIDIA aplicado só no (.+) \((\d+) configurações\)$", m => $"NVIDIA profile applied only to {m.Groups[1].Value} ({m.Groups[2].Value} settings)"),
        P(@"^Configurações NVIDIA do (.+) restauradas$", m => $"{m.Groups[1].Value} NVIDIA settings restored"),
        P(@"^Perfil NVIDIA do (.+): o driver não tem mais esse perfil; backup descartado$", m => $"{m.Groups[1].Value} NVIDIA profile: the driver no longer has it; backup discarded"),
        P(@"^Tentar de novo as (\d+) etapas que falharam$", m => $"Retry the {m.Groups[1].Value} failed steps"),
        P(@"^Reaplicado: (.+)$", m => $"Reapplied: {m.Groups[1].Value}"),
        P(@"^Ajustes reaplicados: (\d+), falhas: (\d+)$", m => $"Settings reapplied: {m.Groups[1].Value}, failures: {m.Groups[2].Value}"),
        P(@"^(.+) em andamento\. Desligar agora pode deixar o Windows com ajustes pela metade\.$", m => $"{T(m, 1)} in progress. Shutting down now may leave Windows half-configured."),
        P(@"^Desligamento do Windows adiado: operação em andamento \((\w+)\)$", m => $"Windows shutdown postponed: operation in progress ({m.Groups[1].Value})"),
        P(@"^Novidades e melhorias do Qrztweaks · (.+)$", m => $"Qrztweaks news and improvements · {m.Groups[1].Value}"),
        // Linhas do histórico gravadas por versões anteriores
        P(@"^Laboratório de desempenho: captura salva \((.+)\)$", m => $"Performance lab: capture saved ({(m.Groups[1].Value == "Só sensores" ? "Sensors only" : T(m, 1))})"),
        P(@"^Placa-mãe detectada: (.+)$", m => $"Motherboard detected: {m.Groups[1].Value}"),
        P(@"^Memória detectada: (\d+) módulo\(s\), (.+)$", m => $"Memory detected: {m.Groups[1].Value} module(s), {m.Groups[2].Value}"),
        P(@"^Recomendações geradas: (\d+) \((\w+), pontuação (\d+), banco (.+)\)$", m => $"Recommendations generated: {m.Groups[1].Value} ({m.Groups[2].Value}, score {m.Groups[3].Value}, database {m.Groups[4].Value})"),
        P(@"^Otimização inteligente: análise concluída \((\d+) recomendados, (\d+) já aplicados\)$", m => $"Smart optimization: analysis finished ({m.Groups[1].Value} recommended, {m.Groups[2].Value} already applied)"),
    };
